62	```dart
63	abstract class ChatRepository {
64	  // createSession / listSessions / cachedSessions / listMessages / cachedMessages /
65	  // setLastActiveSessionId / lastActiveSessionId / sendMessage / retryMessage /
66	  // savedEntryIdFor / recordMessageSaved — unchanged
67	
68	  /// `POST /chat/sessions/:id/insight` (`chat-insight-create`). `Right(content)`
69	  /// only for `status: 'ready'`; every other outcome — a transport failure,
70	  /// or a 200 response with `status: 'failed'` — is `Left` (research.md R7).
71	  /// Retries once via `SessionRepository.refresh()` on `AuthExpiredFailure`,
72	  /// the same shape as every other non-streaming call (research.md R7).
73	  /// Never reads or writes any local cache — nothing about an insight is
74	  /// ever persisted (FR-009).
75	  Future<Either<Failure, String>> createInsight({
76	    required String sessionId,
77	    required InsightTriggerType triggerType,
78	    required String triggerKey,
79	  });
80	}
81	```
