83	`ChatRemoteDataSource`:
84	
85	```dart
86	Future<Either<Failure, String>> createInsight({
87	  required String sessionId,
88	  required InsightTriggerType triggerType,
89	  required String triggerKey,
90	}) async {
91	  final result = await _apiClient.call(
92	    'chat-insight-create',
93	    method: 'POST',
94	    pathSegments: [sessionId],
95	    body: {
96	      'triggerType': _wireTriggerType(triggerType),
97	      'triggerKey': triggerKey,
98	    },
99	  );
100	  return result.flatMap(_parseInsightContent);
101	}
102	
103	String _wireTriggerType(InsightTriggerType type) => switch (type) {
104	  InsightTriggerType.messageCount => 'message_count',
105	  InsightTriggerType.inactivity => 'inactivity',
106	};
107	
108	// research.md R7 — collapses the 200-response `status: 'failed'` outcome
109	// into the same `Left` channel every transport failure already uses.
110	Either<Failure, String> _parseInsightContent(Map<String, dynamic> data) {
111	  try {
112	    if (data['status'] as String? == 'ready') {
113	      return Right(data['content'] as String);
114	    }
115	    return Left(
116	      ErrorMapper.fromResponse({
117	        'code': data['errorCode'],
118	        'message': 'Proactive insight generation failed',
119	        'requestId': data['id'],
120	      }),
121	    );
122	  } on TypeError {
123	    return const Left(_malformedChatFailure);
124	  }
125	}
126	```
