157	
158	```dart
159	class ChatForegroundChanged extends ChatEvent {
160	  const ChatForegroundChanged(this.isForegrounded);
161	  final bool isForegrounded;
162	  @override List<Object?> get props => [isForegrounded];
163	}
164	
165	class InsightInactivityTimerFired extends ChatEvent {
166	  const InsightInactivityTimerFired(this.firedAt);
167	  final DateTime firedAt;
168	  @override List<Object?> get props => [firedAt];
