176	`ChatReady` gains one new field:
177	
178	```dart
179	class ChatReady extends ChatState {
180	  const ChatReady({
181	    required this.sessionId,
182	    required this.messages,
183	    required this.isOffline,
184	    required this.awaitingResponse,
185	    this.loadFailure,
186	    this.bookmarks = const {},
187	    this.insight,                      // NEW — ProactiveInsight?, null = no card visible
188	  });
189	
190	  // ...existing fields...
191	  final ProactiveInsight? insight;
192	
193	  // copyWith(...) gains `ProactiveInsight? insight` + `bool clearInsight = false`,
194	  // the same `clearSessionId`-style boolean-flag shape already used for `sessionId`
195	  // (never the `_unset`-sentinel shape used for `loadFailure`, since `insight`'s
196	  // "clear" case — dismissal — is a named, common operation, not a rare default-preserving one).
197	  // props gains `insight`.
