201	`ChatBloc` gains one new constructor parameter (no new dependency — only a testability seam, research.md R4)
202	and three new handlers; it is otherwise unchanged in its dependency surface:
203	
204	```dart
205	class ChatBloc extends Bloc<ChatEvent, ChatState> {
206	  ChatBloc({
207	    required ChatRepository chatRepository,
208	    required ConnectivityChecker connectivityChecker,
209	    required CreateEntryUseCase createEntryUseCase,
210	    Duration insightInactivityTimeout = const Duration(minutes: 2),   // NEW
211	  }) : ... {
212	    // ...existing on<...> registrations...
213	    on<ChatForegroundChanged>(_onForegroundChanged);                 // NEW
214	    on<InsightInactivityTimerFired>(_onInsightInactivityTimerFired);  // NEW
215	    on<InsightDismissed>(_onInsightDismissed);                       // NEW
216	  }
217	
218	  final Duration _insightInactivityTimeout;
219	
220	  // Insight mechanism bookkeeping — private, never part of ChatState (research.md R1).
221	  int _insightMessageCount = 0;
222	  bool _insightInFlight = false;
223	  InsightTrigger? _pendingInsightTrigger;
224	  int _insightGeneration = 0;
225	  bool _isForegrounded = true;
226	  Timer? _inactivityTimer;
227	
228	  bool get _insightSuspended =>
229	      _insightInFlight ||
230	      _pendingInsightTrigger != null ||
231	      (state case ChatReady(insight: final i) when i != null => true, _ => false);
232	}
233	```
