235	Core helpers:
236	
237	```dart
238	// Conversation (re)opened — FR-009's "counters start fresh" moment.
239	// Called from _onStarted / _onConversationSelected / _onNewConversationRequested,
240	// right before emitting the fresh ChatReady.
241	void _resetInsightMechanism() {
242	  _insightGeneration++;
243	  _insightMessageCount = 0;
244	  _insightInFlight = false;
245	  _pendingInsightTrigger = null;
246	  _inactivityTimer?.cancel();
247	}
248	
249	void _armInactivityTimer() {
250	  _inactivityTimer?.cancel();
251	  if (!_isForegrounded || _insightSuspended) return;
252	  _inactivityTimer = Timer(
253	    _insightInactivityTimeout,
254	    () => add(InsightInactivityTimerFired(DateTime.now())),
255	  );
256	}
257	
258	void _onForegroundChanged(ChatForegroundChanged event, Emitter<ChatState> emit) {
259	  _isForegrounded = event.isForegrounded;
260	  if (!_isForegrounded) {
261	    _inactivityTimer?.cancel();
262	    return;
263	  }
264	  _armInactivityTimer(); // FR-010 — always a fresh 2 minutes, never a resumed partial count
265	}
266	
267	Future<void> _onInsightInactivityTimerFired(
268	  InsightInactivityTimerFired event,
269	  Emitter<ChatState> emit,
270	) async {
271	  final current = state;
272	  if (current is! ChatReady || current.sessionId == null) return; // research.md R6
273	  if (_insightSuspended) return; // defensive — the timer is cancelled the instant suspension begins
274	  final trigger = InsightTrigger(
275	    type: InsightTriggerType.inactivity,
276	    triggerKey: InsightTriggerKeyBuilder.forInactivity(event.firedAt),
277	  );
278	  if (current.awaitingResponse) {
279	    _pendingInsightTrigger ??= trigger; // FR-003 — defer until the turn resolves
280	    return;
281	  }
282	  await _startInsightAttempt(trigger, sessionId: current.sessionId!, emit: emit);
283	}
284	
285	void _onInsightDismissed(InsightDismissed event, Emitter<ChatState> emit) {
286	  final current = state;
287	  if (current is! ChatReady || current.insight == null) return;
288	  emit(current.copyWith(clearInsight: true));
289	  _armInactivityTimer(); // FR-004/FR-008 — suspension ends, fresh window starts
290	}
291	
292	Future<void> _startInsightAttempt(
293	  InsightTrigger trigger, {
294	  required String sessionId,
295	  required Emitter<ChatState> emit,
296	}) async {
297	  _inactivityTimer?.cancel();
298	  _pendingInsightTrigger = null;
299	  _insightInFlight = true;
300	  final generation = _insightGeneration;
301	  final anchorIndex = (state as ChatReady).messages.length;
302	
303	  if (!await _connectivityChecker.hasConnection()) {
304	    _insightInFlight = false; // FR-007 — never attempted; resolved like a failure
305	    if (generation == _insightGeneration) _armInactivityTimer();
306	    return;
307	  }
308	
309	  final result = await _chatRepository.createInsight(
310	    sessionId: sessionId,
311	    triggerType: trigger.type,
312	    triggerKey: trigger.triggerKey,
313	  );
314	
315	  _insightInFlight = false;
316	  if (generation != _insightGeneration) return; // stale — conversation switched away mid-flight
317	
318	  final latest = state;
319	  if (latest is! ChatReady) return;
320	
321	  result.match(
322	    (failure) {
323	      if (failure is AuthExpiredFailure) _reauthController.add(null);
324	      _armInactivityTimer(); // FR-006 — no card, no indicator; occurrence fully resolved
325	    },
326	    (content) => emit(
327	      latest.copyWith(insight: ProactiveInsight(content: content, anchorIndex: anchorIndex)),
328	    ),
329	  );
330	}
331	
332	// Called once per turn resolution — the end of _consumeTurn (after
333	// _reconcileSilentFailure) and inside _failTurn, both now `Future<void>`.
334	Future<void> _onTurnResolved(String sessionId, Emitter<ChatState> emit) async {
335	  final hadPending = _pendingInsightTrigger != null;
336	  final trigger = _pendingInsightTrigger;
337	  if (trigger != null) {
338	    final current = state;
339	    if (current is ChatReady && !current.awaitingResponse) {
340	      await _startInsightAttempt(trigger, sessionId: sessionId, emit: emit);
341	    }
342	  }
343	  // Only re-arm here if a deferred trigger just finished resolving without a
344	  // card (failed/skipped) — a turn with no pending trigger leaves whatever
345	  // timer _onMessageSubmitted already armed at send-time alone (research.md R4).
346	  if (hadPending && !_insightSuspended) _armInactivityTimer();
347	}
348	```
349	
350	Extensions to existing handlers:
351	
352	- **`_onStarted` / `_onConversationSelected` / `_onNewConversationRequested`**: each calls
353	  `_resetInsightMechanism()` before emitting its fresh `ChatReady` (which never passes `insight:`, so it
354	  defaults to `null`), then `_armInactivityTimer()` right after.
355	- **`_onMessageSubmitted`**: immediately after building `optimisticUser`/`optimisticAssistant`, insert:
356	  ```dart
357	  if (!_insightSuspended) {
358	    _insightMessageCount++;
359	    if (_insightMessageCount % 5 == 0) {
360	      _pendingInsightTrigger ??= InsightTrigger(
361	        type: InsightTriggerType.messageCount,
362	        triggerKey: InsightTriggerKeyBuilder.forMessageCount(_insightMessageCount),
363	      );
364	    }
365	  }
366	  _armInactivityTimer(); // FR-001b — resets "time since last message sent" now
367	  ```
368	  then, at the point `_consumeTurn` is awaited (both the brand-new-session and existing-session branches),
369	  nothing else changes — `_consumeTurn` itself now calls `_onTurnResolved` internally (below).
370	- **`_consumeTurn`**: after the existing `await _reconcileSilentFailure(emit, sessionId, assistantId,
371	  generation);` line, add `if (generation == _turnGeneration) await _onTurnResolved(sessionId, emit);` (the
372	  existing `_turnGeneration` guard, not `_insightGeneration` — a stale/abandoned turn should not trigger a fresh
373	  insight attempt on behalf of a conversation no longer active).
374	- **`_failTurn`**: becomes `Future<void> _failTurn(...)`, and after its existing `emit(_applyFailure(...))`
375	  line, adds `await _onTurnResolved(sessionId, emit);` — both call sites (`_onMessageSubmitted`'s and
376	  `_retryLazySessionCreation`'s lazy-`createSession`-failure branches) are updated to `await _failTurn(...)`.
377	- **`close()`**: adds `_inactivityTimer?.cancel();` alongside the existing subscription/controller cleanup.
378	
379	See `contracts/chat-bloc-insight-extension.md` for the full handler listing and test-scenario table.
